ApiConfigText.value:
"{
  "format": "warudodc.api-config.experimental",
  "version": 2,
  "events": [
    {
      "route": "adapter_to_link",
      "key": "autonomy.mode.free",
      "enabled": true,
      "description": "请求进入自由模式，不自动移动角色；现有返回待命过渡期间拒绝。业务结果经autonomy.state.result返回。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "autonomy.mode.standby",
      "enabled": true,
      "description": "请求沿既有返回待命流程回到待命；实际完成后经autonomy.state.result回执。重复在途请求拒绝，ACK不表示模式已改变。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "autonomy.move_by",
      "enabled": true,
      "description": "按世界坐标相对当前位置移动 delta，沿用自主行动守卫与软边界。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "delta",
          "kind": "vector3",
          "description": "世界坐标位移（米），不是角色局部前后左右。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "autonomy.move_to",
      "enabled": true,
      "description": "请求角色自主移动到目标世界坐标；最终是否执行由主场景 Autonomy Controller 决定。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "target",
          "kind": "vector3",
          "description": "期望到达的世界坐标；主场景会将其限制在桌面软边界内。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "autonomy.rotate_by",
      "enabled": true,
      "description": "水平自主转向，遵守本地交互策略，实际执行由 Locomotion Turn 负责。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "delta_yaw",
          "kind": "float",
          "description": "相对当前水平朝向的增量（度），限制 [-180,180]，走最短路径。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "autonomy.rotate_to",
      "enabled": true,
      "description": "水平自主转向，遵守本地交互策略，实际执行由 Locomotion Turn 负责。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "yaw",
          "kind": "float",
          "description": "世界水平朝向（度），限制 [0,360]。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "expression.aggrieved",
      "enabled": true,
      "description": "请求显示委屈：被误解、受到冷落或希望得到安慰；区别于一般悲伤、责怪和愤怒。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.bored",
      "enabled": true,
      "description": "请求显示无聊：兴致缺缺、敷衍或等待太久；不同于身体疲倦、愤怒或受到冒犯。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.confused",
      "enabled": true,
      "description": "请求显示疑惑表情；按当前情绪选择本地图内差分，自动恢复到届时有效表情，不抢占交互表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.disgusted",
      "enabled": true,
      "description": "请求显示嫌弃：对具体对象或行为表示排斥、嫌弃或不想靠近；不用于单纯没听懂。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.displeased",
      "enabled": true,
      "description": "请求显示不满：抗议、责怪或表达个人边界的即时反应；不是改变角色长期基础情绪。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.embarrassed",
      "enabled": true,
      "description": "请求显示尴尬：出糗、被拆穿或社交窘迫；正向亲昵和夸奖后的羞涩使用expression.shy。仅提交REQUESTED，按当前场景规则合成并自动恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.expectant",
      "enabled": true,
      "description": "请求显示期待：期待答案、礼物或接下来的互动，积极地等待；不是已经得到结果后的得意。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.fearful",
      "enabled": true,
      "description": "请求显示害怕：受到威胁、恐惧或受惊；普通意外消息使用惊讶，不要把惊喜解释为恐惧。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.playful",
      "enabled": true,
      "description": "请求显示俏皮：调侃、逗弄或善意使坏时的俏皮反应；不要用于严肃关切或对方明显不适时。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.relieved",
      "enabled": true,
      "description": "请求显示释然：放下顾虑、确认安全或松了一口气；关注担忧解除的转折，而非所有普通开心。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.shy",
      "enabled": true,
      "description": "请求显示害羞：被亲近或夸奖后的正向羞涩、欲言又止；出糗和社交窘迫使用尴尬。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.skeptical",
      "enabled": true,
      "description": "请求显示怀疑：已经听懂但不太相信、质疑真实性或动机；不理解含义时使用困惑。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.smug",
      "enabled": true,
      "description": "请求显示得意：被夸奖、完成事情或小小炫耀后的自得；不是所有开心片段都需要得意。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.speechless",
      "enabled": true,
      "description": "请求显示无语表情；按当前情绪选择本地图内差分，自动恢复到届时有效表情，不抢占交互表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.surprised",
      "enabled": true,
      "description": "请求显示惊讶表情；按当前情绪选择本地图内差分，自动恢复到届时有效表情，不抢占交互表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.tender",
      "enabled": true,
      "description": "请求显示温柔：安慰、关爱或温柔亲昵地回应；无需每次礼貌回答都添加此表情。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.thinking",
      "enabled": true,
      "description": "请求思考表情；场景DurationSeconds=0持续到替换/释放，正数限时；不代表模型内部推理。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.tired",
      "enabled": true,
      "description": "请求显示疲惫：对话中展示疲劳、困倦或勉强打起精神；仅是表现请求，不证明本地生理状态已产生。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.worried",
      "enabled": true,
      "description": "请求显示担忧：担心对方、犹豫或预感不妙；是关切，不等于自己已经受到直接威胁。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "idle.return_normal_pose",
      "enabled": true,
      "description": "回归平时待命动作并按variant选择站姿；结束当前普通肢体表现，不切换活动模式，不打断移动或背部拖拽。非法差分／受保护占用拒绝时不改变所选站姿。经autonomy.state.result报告本地处理，不代表动画完成。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "variant",
          "kind": "integer",
          "description": "待机姿势差分：-1=沿用当前所选；0=一般，1=双手前放，2=双手后放，3=单手撑腰，4=侧站抱臂。0..4仅在本地受理后更新所选姿势，之后回归待机继续使用；不自动随机切换。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "performance.concern",
      "enabled": true,
      "description": "尝试进入担心关切姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.cute",
      "enabled": true,
      "description": "尝试进入卖萌姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "variant",
          "kind": "integer",
          "description": "姿势差分：0=双手置于身前，1=身体向前倾；选择一种，不移动角色根位置。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "performance.facepalm",
      "enabled": true,
      "description": "尝试进入扶脸懊恼姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.flex",
      "enabled": true,
      "description": "尝试进入展示力量姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.hand_behind_head",
      "enabled": true,
      "description": "尝试进入扶后脑勺姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.hand_on_chest",
      "enabled": true,
      "description": "尝试进入认真表态姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.hands_on_hips",
      "enabled": true,
      "description": "请求身体明显前倾的双手叉腰姿态，作为刻意强调、抗议或质问的肢体表现；不自动改变表情。普通单手撑腰站姿使用idle.return_normal_pose的variant=3。保持到明确回归待机、获准替换或场景清理。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.invite_hug",
      "enabled": true,
      "description": "尝试进入邀请拥抱姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.protest",
      "enabled": true,
      "description": "尝试进入赌气抗议姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.refuse",
      "enabled": true,
      "description": "尝试进入拒绝姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "variant",
          "kind": "integer",
          "description": "姿势差分：0=普通拒绝姿态，1=双臂比叉的明确拒绝；仅接受0或1。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "performance.reserved",
      "enabled": true,
      "description": "尝试进入拘谨姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.show_back",
      "enabled": true,
      "description": "尝试进入展示背部姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.shrug",
      "enabled": true,
      "description": "尝试进入耸肩姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.slouch",
      "enabled": true,
      "description": "尝试进入垂头丧气姿态；不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.thinking",
      "enabled": true,
      "description": "姿势差分：0=原思考姿势，1=双腿交叉思考；仅接受0或1。仍为持续思考姿态及所属思考表情组合，统一回归待机结束。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "variant",
          "kind": "integer",
          "description": "姿势差分：0=原思考姿势，1=双腿交叉思考；仅接受0或1。仍为持续思考姿态及所属思考表情组合，统一回归待机结束。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "performance.wave_once",
      "enabled": true,
      "description": "姿势差分：0=举臂挥动（原动作），1=双手挥动，2=单手挥动；仅接受0、1、2。保持原有限时挥手，不自动改变表情。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "variant",
          "kind": "integer",
          "description": "姿势差分：0=举臂挥动（原动作），1=双手挥动，2=单手挥动；仅接受0、1、2。保持原有限时挥手，不自动改变表情。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "speak.calm",
      "enabled": true,
      "description": "以克制、沉稳的手势分析或说明，适合认真讨论。同风格跨片段保持；正常结束统一回归待机，打断时不补播收尾。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "speak.chatty",
      "enabled": true,
      "description": "说话时手部动作丰富，适合较活泼的叙述和聊天。同风格跨片段保持；正常结束统一回归待机，打断时不补播收尾。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "speak.composed",
      "enabled": true,
      "description": "抱臂、克制而冷静地说话，适合保留意见或从容分析。同风格跨片段保持；正常结束统一回归待机，打断时不补播收尾。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "speak.excited",
      "enabled": true,
      "description": "以较活跃的肢体姿态兴奋地讲述，适合热切分享或激动回应。同风格跨片段保持；正常结束统一回归待机，打断时不补播收尾。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "speak.explaining",
      "enabled": true,
      "description": "以手势解释、说明或梳理一件事，适合有一定长度的讲解。同风格跨片段保持；正常结束统一回归待机，打断时不补播收尾。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "speak.pointing",
      "enabled": true,
      "description": "以较轻松的指向手势说话，适合打趣或轻佻地强调；不是指责动作。同风格跨片段保持；正常结束统一回归待机，打断时不补播收尾。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "speak.pouting",
      "enabled": true,
      "description": "抱臂并带有赌气、抗议或不满的身体态度说话。同风格跨片段保持；正常结束统一回归待机，打断时不补播收尾。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "speak.scolding",
      "enabled": true,
      "description": "手指朝向屏幕，带有强调、责备或告诫的身体态度。同风格跨片段保持；正常结束统一回归待机，打断时不补播收尾。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "speak.shy",
      "enabled": true,
      "description": "以拘谨、羞怯的身体姿态交谈，适合不好意思或含蓄回应。同风格跨片段保持；正常结束统一回归待机，打断时不补播收尾。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "link_to_adapter",
      "key": "autonomy.move_by.result",
      "enabled": true,
      "description": "实际到达后返回；reply_to 关联 autonomy.move_by，拒绝或中止不伪报成功。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "position",
          "kind": "vector3",
          "description": "实际完成世界坐标。"
        },
        {
          "key": "status",
          "kind": "string",
          "description": "完成为 completed。"
        }
      ]
    },
    {
      "route": "link_to_adapter",
      "key": "autonomy.move_to.result",
      "enabled": true,
      "description": "角色确实到达本次自主移动目标后返回；reply_to 关联原 autonomy.move_to 事件。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "position",
          "kind": "vector3",
          "description": "完成时角色节点的世界坐标。"
        },
        {
          "key": "status",
          "kind": "string",
          "description": "业务终态；首版成功路径固定为 completed。"
        }
      ]
    },
    {
      "route": "link_to_adapter",
